-- 约定：本表由 load_to_mysql.py --init 一次性建表（init 只跑一次）；用 CREATE ... IF NOT EXISTS，勿加回 DROP TABLE（会清空真实库数据）。
CREATE TABLE IF NOT EXISTS insurer_financials
(
    company_code                                               CHAR(10)       NOT NULL,
    fiscal_year                                                SMALLINT       NOT NULL COMMENT '报告期(年度)',
    total_operating_revenue                                    DECIMAL(28, 4) NULL COMMENT '营业总收入(元；东财主要指标接口 total_revenue)',
    earned_premiums_or_insurance_revenue                       DECIMAL(28, 4) NULL COMMENT '已赚保费/保险服务收入(元；2022重述行起为IFRS17保险服务收入)',
    return_on_assets                                           DECIMAL(12, 4) NULL COMMENT '总资产净利率(%,净利润/平均总资产)',
    liability_to_asset_ratio                                   DECIMAL(12, 4) NULL COMMENT '资产负债率(%)',
    equity_multiplier                                          DECIMAL(12, 4) NULL COMMENT '权益乘数(倍,总资产/股东权益合计)',
    total_shares                                               BIGINT         NULL COMMENT '总股本(股,接口当前股本快照逐年回填)',
    equity_asset_ratio                                         DECIMAL(12, 4) NULL COMMENT '权益资产比(%,股东权益合计/总资产,自算)',
    net_investment_yield                                       DECIMAL(12, 4) NULL COMMENT '净投资收益率%',
    total_investment_yield                                     DECIMAL(12, 4) NULL COMMENT '总投资收益率%',
    comprehensive_investment_yield                             DECIMAL(12, 4) NULL COMMENT '综合投资收益率%(仅中国太平2023-2025,含FVOCI公允价值变动)',
    new_business_value_margin                                  DECIMAL(12, 4) NULL COMMENT '新业务价值率%(各家分母不一)',
    life_insurance_subsidiary_comprehensive_solvency_ratio     DECIMAL(12, 4) NULL COMMENT '寿险子公司(太平人寿)综合偿付能力充足率%',
    property_casualty_subsidiary_comprehensive_solvency_ratio  DECIMAL(12, 4) NULL COMMENT '财险子公司(太平财险)综合偿付能力充足率%',
    pension_insurance_subsidiary_comprehensive_solvency_ratio  DECIMAL(12, 4) NULL COMMENT '养老险子公司(太平养老)综合偿付能力充足率%',
    life_insurance_subsidiary_core_solvency_ratio              DECIMAL(12, 4) NULL COMMENT '寿险子公司(太平人寿)核心偿付能力充足率%',
    property_casualty_subsidiary_core_solvency_ratio           DECIMAL(12, 4) NULL COMMENT '财险子公司(太平财险)核心偿付能力充足率%',
    pension_insurance_subsidiary_core_solvency_ratio           DECIMAL(12, 4) NULL COMMENT '养老险子公司(太平养老)核心偿付能力充足率%',
    total_investment_assets                                    DECIMAL(28, 4) NULL COMMENT '投资资产合计(元；A股五家为脚本自建口径,太平为年报披露数)',
    life_insurance_new_business_value                          DECIMAL(28, 4) NULL COMMENT '寿险一年新业务价值(元,扣除要求资本成本后)',
    employee_count                                             INT            NULL COMMENT '员工人数(人)',
    comprehensive_solvency_ratio                               DECIMAL(12, 4) NULL COMMENT '综合偿付能力充足率%(偿一代时期为偿付能力充足率)',
    life_insurance_surrender_rate                              DECIMAL(12, 4) NULL COMMENT '寿险退保率%',
    assumed_reinsurance_premiums                               DECIMAL(28, 4) NULL COMMENT '分保费收入(元,保险业务收入中的分入保费)',
    banking_net_interest_income                                DECIMAL(28, 4) NULL COMMENT '银行业务利息净收入(元,平安合并平安银行)',
    non_insurance_net_fee_commission_income                    DECIMAL(28, 4) NULL COMMENT '非保险业务手续费及佣金净收入(元,平安)',
    investment_income                                          DECIMAL(28, 4) NULL COMMENT '投资收益(元)',
    investment_income_from_associates_and_joint_ventures       DECIMAL(28, 4) NULL COMMENT '对联营企业和合营企业的投资收益(元)',
    gains_from_changes_in_fair_value                           DECIMAL(28, 4) NULL COMMENT '公允价值变动收益(损失为负)(元)',
    foreign_exchange_gain_loss                                 DECIMAL(28, 4) NULL COMMENT '汇兑损益(元,损失为负)',
    other_operating_income                                     DECIMAL(28, 4) NULL COMMENT '其他业务收入(元)',
    operating_expenses                                         DECIMAL(28, 4) NULL COMMENT '营业支出(元)',
    surrender_payments                                         DECIMAL(28, 4) NULL COMMENT '退保金(元)',
    claims_and_policyholder_benefits                           DECIMAL(28, 4) NULL COMMENT '赔付支出(元,原保险合同赔付总额,未扣摊回；IFRS17后无)',
    increase_in_insurance_liability_reserves                   DECIMAL(28, 4) NULL COMMENT '提取保险责任准备金(元,未决+寿险+长期健康险,未扣摊回；IFRS17后无)',
    policyholder_dividends                                     DECIMAL(28, 4) NULL COMMENT '保单红利支出(元)',
    assumed_reinsurance_expenses                               DECIMAL(28, 4) NULL COMMENT '分保费用(元,分入业务支付给分出人的分保手续费等)',
    fee_commission_expense                                     DECIMAL(28, 4) NULL COMMENT '手续费及佣金支出(元；旧准则为保险业务佣金,IFRS17后仅非保险合同部分)',
    general_admin_expenses                                     DECIMAL(28, 4) NULL COMMENT '管理费用/业务及管理费(元)',
    interest_expense                                           DECIMAL(28, 4) NULL COMMENT '利息支出(元；平安为非银行业务利息支出)',
    other_business_costs                                       DECIMAL(28, 4) NULL COMMENT '其他业务成本(元)',
    credit_impairment_loss                                     DECIMAL(28, 4) NULL COMMENT '信用减值损失(元；水泥/地产/运营商源值以负数表示损失)',
    asset_impairment_loss                                      DECIMAL(28, 4) NULL COMMENT '资产减值损失(元；水泥/地产/运营商源值以负数表示损失)',
    taxes_and_surcharges                                       DECIMAL(28, 4) NULL COMMENT '税金及附加(元)',
    income_tax_expense                                         DECIMAL(28, 4) NULL COMMENT '所得税费用(元)',
    net_profit_excluding_non_recurring_items_attr_parent       DECIMAL(28, 4) NULL COMMENT '扣除非经常性损益后归母净利润(元)',
    net_profit_attr_non_controlling_interests                  DECIMAL(28, 4) NULL COMMENT '少数股东损益(元)',
    other_comprehensive_income                                 DECIMAL(28, 4) NULL COMMENT '其他综合收益的税后净额(元,利润表当期发生额)',
    total_comprehensive_income                                 DECIMAL(28, 4) NULL COMMENT '综合收益总额(元)',
    cash_and_bank_balances                                     DECIMAL(28, 4) NULL COMMENT '货币资金(元)',
    term_deposits                                              DECIMAL(28, 4) NULL COMMENT '定期存款(元)',
    reverse_repurchase_assets                                  DECIMAL(28, 4) NULL COMMENT '买入返售金融资产(元)',
    trading_financial_assets                                   DECIMAL(28, 4) NULL COMMENT '交易性金融资产(元)',
    debt_investments                                           DECIMAL(28, 4) NULL COMMENT '债权投资(元,新金融工具准则,摊余成本计量)',
    other_debt_investments                                     DECIMAL(28, 4) NULL COMMENT '其他债权投资(元,新金融工具准则,FVOCI债务工具)',
    other_equity_investments                                   DECIMAL(28, 4) NULL COMMENT '其他权益工具投资(元,FVOCI权益工具)',
    fvtpl_financial_assets                                     DECIMAL(28, 4) NULL COMMENT '以公允价值计量且其变动计入当期损益的金融资产(元)',
    fvtoci_financial_assets                                    DECIMAL(28, 4) NULL COMMENT '以公允价值计量且其变动计入其他综合收益的金融资产(元)',
    amortized_cost_financial_assets                            DECIMAL(28, 4) NULL COMMENT '以摊余成本计量的金融资产(元)',
    available_for_sale_financial_assets                        DECIMAL(28, 4) NULL COMMENT '可供出售金融资产(元,旧金融工具准则)',
    held_to_maturity_investments                               DECIMAL(28, 4) NULL COMMENT '持有至到期投资(元,旧金融工具准则)',
    debt_investment_plans                                      DECIMAL(28, 4) NULL COMMENT '债权计划投资(元,保险资管债权投资计划)',
    long_term_equity_investments                               DECIMAL(28, 4) NULL COMMENT '长期股权投资(元)',
    investment_properties                                      DECIMAL(28, 4) NULL COMMENT '投资性房地产(元)',
    policy_loans                                               DECIMAL(28, 4) NULL COMMENT '保户质押贷款(元)',
    premiums_receivable                                        DECIMAL(28, 4) NULL COMMENT '应收保费(元)',
    reinsurance_receivables                                    DECIMAL(28, 4) NULL COMMENT '应收分保账款(元)',
    independent_account_assets                                 DECIMAL(28, 4) NULL COMMENT '独立账户资产(元,投连险独立账户)',
    fixed_assets                                               DECIMAL(28, 4) NULL COMMENT '固定资产(元)',
    deferred_tax_assets                                        DECIMAL(28, 4) NULL COMMENT '递延所得税资产(元)',
    customer_deposits_balance_sheet                            DECIMAL(28, 4) NULL COMMENT '吸收存款(元,资产负债表列报；仅平安合并平安银行有实值)',
    net_loans                                                  DECIMAL(28, 4) NULL COMMENT '发放贷款及垫款/贷款(元；平安含平安银行,国寿为含保户质押贷款的「贷款」)',
    insurance_contract_reserves                                DECIMAL(28, 4) NULL COMMENT '保险合同准备金(元,旧准则=未到期+未决+寿险+长期健康险)',
    outstanding_claims_reserves                                DECIMAL(28, 4) NULL COMMENT '未决赔款准备金(元,旧准则；IFRS17后无)',
    unearned_premium_reserves                                  DECIMAL(28, 4) NULL COMMENT '未到期责任准备金(元,旧准则；IFRS17后无)',
    life_insurance_reserves                                    DECIMAL(28, 4) NULL COMMENT '寿险责任准备金(元,旧准则；IFRS17后无)',
    long_term_health_insurance_reserves                        DECIMAL(28, 4) NULL COMMENT '长期健康险责任准备金(元,旧准则；IFRS17后无)',
    policyholder_deposits_and_investment_funds                 DECIMAL(28, 4) NULL COMMENT '保户储金及投资款(元)',
    repurchase_agreements                                      DECIMAL(28, 4) NULL COMMENT '卖出回购金融资产款(元)',
    bonds_payable                                              DECIMAL(28, 4) NULL COMMENT '应付债券(元)',
    subordinated_bonds_payable                                 DECIMAL(28, 4) NULL COMMENT '应付次级债(元)',
    independent_account_liabilities                            DECIMAL(28, 4) NULL COMMENT '独立账户负债(元)',
    equity_attr_non_controlling_interests                      DECIMAL(28, 4) NULL COMMENT '少数股东权益(元)',
    general_risk_reserve                                       DECIMAL(28, 4) NULL COMMENT '一般风险准备(元,股东权益项下)',
    undistributed_profits                                      DECIMAL(28, 4) NULL COMMENT '未分配利润(元)',
    accumulated_other_comprehensive_income                     DECIMAL(28, 4) NULL COMMENT '其他综合收益(元,资产负债表权益项下累计余额,可为负)',
    cash_received_from_direct_insurance_premiums               DECIMAL(28, 4) NULL COMMENT '收到原保险合同保费取得的现金(元)',
    cash_paid_for_direct_insurance_claims                      DECIMAL(28, 4) NULL COMMENT '支付原保险合同赔付款项的现金(元)',
    earned_premiums_or_insurance_revenue_as_reported           DECIMAL(28, 4) NULL COMMENT '已赚保费/保险服务收入(元,主要指标口径,当年原披露值)',
    total_minus_net_investment_yield                           DECIMAL(12, 4) NULL COMMENT '总投资收益率−净投资收益率(百分点)',
    return_on_assets_attr_parent                               DECIMAL(12, 4) NULL COMMENT '归母总资产收益率(%,归母净利润/期初期末平均总资产,自算)',
    hong_kong_dollar_exchange_rate_used                        DECIMAL(16, 6) NULL COMMENT '折算用汇率(1 港元合人民币；当年最后一个交易日中间价,中国太平港币金额按它折人民币)',
    implied_hong_kong_dollar_exchange_rate                     DECIMAL(16, 6) NULL COMMENT '隐含汇率(接口人民币总资产÷年报港币总资产；与折算用汇率不一致时见 exchange_rate_check_note)',
    exchange_rate_check_note                                   TEXT           NULL COMMENT '汇率核对说明(隐含汇率与官方中间价不一致的年份)',
    equity_check_note                                          TEXT           NULL COMMENT '权益核对说明(年报原披露权益与接口金额口径差异)',
    restatement_note                                           TEXT           NULL COMMENT '版本说明(该年金额为后一年年报重列数等)',
    source                                                     TEXT           NULL COMMENT '数据来源',
    PRIMARY KEY (company_code, fiscal_year),
    CONSTRAINT fk_insurer_financials_company FOREIGN KEY (company_code) REFERENCES company (company_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT ='保险业专属年度指标（insurer_*_annual.json 里 financials 公共列以外的字段）：与 financials 同主键按需 JOIN，公共列不在此重复；JSON 源字段名与倍数见 data/extract/industry_columns.py，金额统一为元';
